const D = { density:.5, complexity:.5, speed:1, energy:.6, hue:40, scale:1, x:.5, y:.5, style:'sand', act:'settle', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const u = Math.min(width,height);
const st = P.style;
const intn = (K.intensity!=null?K.intensity:.6);
const fr = i => { const s=Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s-Math.floor(s); };
const key = width+'x'+height+st+((P.seed|0)%1000)+Math.round(P.hue);

// particle count (0 for field-render styles)
const N = (st==='schematic'||st==='thermal') ? 0 : Math.floor(150 + P.density*350);

// seeded rng + layout rebuild
if (S.seedUsed!==P.seed || !S.rnd){
  S.seedUsed=P.seed;
  let z=(P.seed*2654435761 + 22391)>>>0;
  S.rnd=()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
}
if (!S.ps || S.ps.length!==N){
  S.ps=[]; for(let i=0;i<N;i++) S.ps.push({a:S.rnd(), b:S.rnd()});
}
const rnd=S.rnd;

// cached plate base (full-bleed)
if (!S.base || S.baseKey!==key){
  const g=createGraphics(width,height); g.colorMode(HSB,360,100,100,100); g.noStroke();
  if (st==='ink') g.background(42,7,85);
  else if (st==='schematic') g.background(220,60,12);
  else if (st==='brass') g.background((P.hue*0.2+30)%360,48,11);
  else if (st==='thermal') g.background(250,60,6);
  else g.background((P.hue*0.12+220)%360,34,7);
  const grains = st==='ink'?900:520;
  for(let i=0;i<grains;i++){
    const gx=fr(i*3+1)*width, gy=fr(i*3+2)*height, d=1+fr(i*3)*2.2;
    if (st==='ink'){ g.fill(42,10,68,9); g.circle(gx,gy,d); }
    else if (st==='schematic'){ g.fill(220,50,20,7); g.circle(gx,gy,d); }
    else { g.fill(0,0,fr(i*3+3)>0.5?20:2, 8); g.circle(gx,gy,d); }
  }
  S.base=g; S.baseKey=key;
}
image(S.base,0,0);

// modes: base + per-section seeded jumps + continuous real-time drift
const cx0 = 2 + P.complexity*6.5;
const sec = Math.floor(K.section||0);
let m = cx0 + Math.floor(fr(sec+11)*3);
let n = cx0*0.62 + 1 + Math.floor(fr(sec+29)*3);
const drift = 0.3 + P.speed*0.22;
m += Math.sin(K.t*0.055*P.speed)*drift;
n += Math.cos(K.t*0.043*P.speed + 1.1)*drift;
if (P.act==='cascade'){ const climb=(K.t*0.02*P.speed)%6; m+=climb; n+=climb*0.7; }
else if (P.act==='resonate'){ const ring=K.pulse*0.9 + A.bass*1.3; m+=ring; n+=ring*0.6; }
const phx=(P.x-0.5)*0.6, phy=(P.y-0.5)*0.6;
const field=(a,b)=>{ const aa=a+phx, bb=b+phy; return Math.cos(m*Math.PI*aa)*Math.cos(n*Math.PI*bb)+Math.cos(n*Math.PI*aa)*Math.cos(m*Math.PI*bb); };

if (st==='thermal'){
  noStroke();
  const G=46, cw=width/G, ch=height/G;
  for(let gy=0;gy<G;gy++) for(let gx=0;gx<G;gx++){
    const v=Math.abs(field((gx+0.5)/G,(gy+0.5)/G))/2;
    const hh=(255 - v*255+360)%360, ss=88-v*64, br=Math.min(96, 6+v*(72+intn*18)+K.pulse*7);
    fill(hh,ss,br,100); rect(gx*cw,gy*ch,cw+1,ch+1);
  }
} else if (st==='schematic'){
  const G=Math.max(30, Math.round(30+P.complexity*30)), cw=width/G, ch=height/G;
  const val=[];
  for(let gy=0;gy<=G;gy++){ val[gy]=[]; for(let gx=0;gx<=G;gx++) val[gy][gx]=field(gx/G,gy/G); }
  stroke(190,70,95, 55+K.pulse*30); strokeWeight(1.2); noFill();
  for(let gy=0;gy<G;gy++) for(let gx=0;gx<G;gx++){
    const v0=val[gy][gx],v1=val[gy][gx+1],v2=val[gy+1][gx+1],v3=val[gy+1][gx];
    const x0=gx*cw,y0=gy*ch,x1=x0+cw,y1=y0+ch, pts=[];
    const ip=(xa,ya,xb,yb,va,vb)=>{ const t=va/(va-vb); pts.push([xa+(xb-xa)*t, ya+(yb-ya)*t]); };
    if((v0>0)!==(v1>0)) ip(x0,y0,x1,y0,v0,v1);
    if((v1>0)!==(v2>0)) ip(x1,y0,x1,y1,v1,v2);
    if((v2>0)!==(v3>0)) ip(x1,y1,x0,y1,v2,v3);
    if((v3>0)!==(v0>0)) ip(x0,y1,x0,y0,v3,v0);
    if(pts.length>=2) line(pts[0][0],pts[0][1],pts[1][0],pts[1][1]);
  }
} else {
  // sand / brass / ink — stochastic Chladni particle migration to nodes
  noStroke();
  const vib=(0.006+P.energy*0.017)*(0.7+intn*0.6);
  const minW=0.0006+P.energy*0.001;
  const gs=u*(0.004+P.energy*0.003)*P.scale;
  for(let i=0;i<S.ps.length;i++){
    const p=S.ps[i];
    const amp=Math.abs(field(p.a,p.b))/2;
    const disp=minW + amp*amp*(vib + A.bass*0.02);
    const ang=rnd()*6.2832;
    p.a+=Math.cos(ang)*disp; p.b+=Math.sin(ang)*disp;
    if(p.a<0)p.a=-p.a; else if(p.a>1)p.a=2-p.a;
    if(p.b<0)p.b=-p.b; else if(p.b>1)p.b=2-p.b;
    const sx=p.a*width, sy=p.b*height;
    const settle=1-Math.min(1,amp*1.4);
    let h,s,bb,al;
    if(st==='ink'){ h=225; s=14; bb=8; al=42+settle*46; }
    else if(st==='brass'){ h=(P.hue*0.6+34)%360; s=58-settle*22; bb=52+settle*44; al=46+settle*40; }
    else { h=P.hue%360; s=24-settle*15; bb=68+settle*30; al=44+settle*40; }
    fill(h,s,bb,al);
    circle(sx,sy, gs*(0.7+settle*0.7));
  }
}
blendMode(BLEND);
drawingContext.shadowBlur=0;
